(function () {
  const footerVid = document.querySelector('.footer-bg-vid');
  if (!footerVid) return;

  const footerObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          footerVid.play();
        } else {
          footerVid.pause();
          footerVid.currentTime = 0;
        }
      });
    },
    { threshold: 0.4 }
  );

  footerObserver.observe(footerVid);
})();

(async () => {
  // Только десктоп (≥480px)
  if (!window.matchMedia('(min-width: 480px)').matches) return;

  const AF_URL = '/reference/assets/3a67aab28544-scroll-15_1920-265-18.af';
  const canvas = document.getElementById('af-canvas');
  const imgWrap = document.querySelector('.about-image-wrapper');
  const section = document.querySelector('.section-about');
  if (!canvas || !imgWrap || !section) return;

  // Фолбэк: нет WebCodecs → остаёмся со статичной .about-image
  if (!('VideoDecoder' in window)) {
    canvas.remove();
    return;
  }

  const ctx = canvas.getContext('2d', { alpha: false });
  let canvasSized = false;
  let firstFrameDrawn = false;

  const af = new window.ActiveFrame(AF_URL, {
    hardwareAcceleration: 'prefer-hardware',
    process: (frame) => {
      if (!canvasSized) {
        canvas.width = frame.displayWidth;
        canvas.height = frame.displayHeight;
        canvasSized = true;
      }
      ctx.drawImage(frame, 0, 0, canvas.width, canvas.height);
      if (!firstFrameDrawn) {
        firstFrameDrawn = true;
        canvas.classList.add('is-ready');
      }
    }
  });

  await af.loading;
  const totalFrames = af.manifest.totalFrames;
  af.setFrame(0);

  const progress = { p: 0 };
  let lastFrame = -1;

  gsap.to(progress, {
    p: 1,
    ease: 'none',
    scrollTrigger: {
      trigger: section,
      start: 'top top-=100%',
      end: '+=300%',
      scrub: true,
    },
    onUpdate() {
      const f = Math.round(progress.p * (totalFrames - 1));
      if (f !== lastFrame) {
        lastFrame = f;
        af.setFrame(f);
      }
    }
  });
})();

const observer = new MutationObserver(function() {
  const banner = document.querySelector('#ez-cookie-notification');
  if (banner) {
    observer.disconnect();

    const accept = document.querySelector('#ez-cookie-notification__accept');
    const decline = document.querySelector('#ez-cookie-notification__decline');

    const gradientHTML = '<div class="button-main-gradient"><div class="button-main-gradient-blur"></div></div>';

    if (accept) {
      accept.className = 'button-main-card is-black';
      accept.innerHTML = `<div class="button-main-text">${accept.textContent}</div>${gradientHTML}`;
    }
    if (decline) {
      decline.className = 'button-main-card';
      decline.innerHTML = `<div class="button-main-text">${decline.textContent}</div>${gradientHTML}`;
    }

    setTimeout(function() {
      banner.classList.add('visible');
    }, 6000);
  }
});

observer.observe(document.body, { childList: true, subtree: true });

