function initLenis() {
  // отключаем Lenis на экранах 479px и меньше
  if (window.innerWidth <= 479) return;

  lenis = new Lenis({
    lerp: 0.12
  });

  lenis.on("scroll", ScrollTrigger.update);

  gsap.ticker.add((e) => {
    lenis.raf(e * 1000);
  });

  gsap.ticker.lagSmoothing(0);
}

document.addEventListener("DOMContentLoaded", () => {
  initLenis();
});
